// The keyboard's tuning (forte/tuning.h): each key's frequency over equal temperament at A = 440 Hz.
inline forte::Tuning tuningOf(const double *P) {
  const double custom[forte::kCustomCents] = {P[p::cents1], P[p::cents2], P[p::cents3], P[p::cents4], P[p::cents5], P[p::cents6], P[p::cents7], P[p::cents8], P[p::cents9], P[p::cents10], P[p::cents11]};
  return forte::makeTuning(P[p::pitch], P[p::temperament], P[p::tuningRoot], custom);
}

// The plugin's description. The port supplies its engine, and midiVelocity when the
// descriptor maps MIDI velocity itself (this one does not).
inline InstrumentInfo info(Engine *(*create)(double fs), double (*midiVelocity)(double) = nullptr) {
  return InstrumentInfo{
    .slug = "trautonium", .name = "Trautonium", .version = FORTE_INSTRUMENT_VERSION,
    .description = "A neon lamp flashing as its capacitor charges through a wire pressed onto a rail: the finger slides the pitch, lamps that fire on every n-th flash add the subharmonics, and every flash rings fixed resonant circuits like a voice’s formants.", .auSubtype = "Trau",
    .vst3Id = {0x55, 0x20, 0x56, 0xdd, 0xac, 0x79, 0x4b, 0xcb, 0x7a, 0x60, 0x02, 0x07, 0x01, 0xa9, 0xeb, 0x4b},
    .params = kParams, .paramCount = p::count,
    .presets = kPresets, .presetCount = 14,
    .keep = kKeep, .keepCount = 18,
    .keyLo = 21, .keyHi = 108, .space = Space::hold,
    .modWheel = p::f1, .modWheelMax = 6000,
    .controllers = kControllers, .controllerCount = 6,
    .chain = {.volume = p::volume, .room = p::room, .roomSeconds = 2, .roomGain = 0.6, .venue = p::venue, .tone = -1, .trimDb = -4},
    .midiVelocity = midiVelocity, .create = create,
  };
}

